45 EP — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bredouillement.html&quot; title=&quot;Bredouillement&quot;&gt;bredouillement&lt;/a&gt;&lt;/i&gt; (3 EP, DD 21), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chirurgie-Psychique.html&quot; title=&quot;Chirurgie psychique&quot;&gt;chirurgie psychique&lt;/a&gt;&lt;/i&gt; (6 EP), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Coup-Mental-Vi.html&quot; title=&quot;Coup mental VI&quot;&gt;coup mental VI&lt;/a&gt;&lt;/i&gt; (6 EP, DD 24), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;go&#251;t.html&quot; title=&quot;D&#233;go&#251;t&quot;&gt;d&#233;go&#251;t&lt;/a&gt;&lt;/i&gt; (2 EP, DD 20), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Effacement-De-Lesprit.html&quot; title=&quot;Effacement de l&amp;#39;esprit&quot;&gt;effacement de l&#39;esprit&lt;/a&gt;&lt;/i&gt; (4 EP, DD 22), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;veil.html&quot; title=&quot;&#201;veil&quot;&gt;&#233;veil&lt;/a&gt;&lt;/i&gt; (5 EP), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;veil-De-Cr&#233;ature-Artificielle.html&quot; title=&quot;&#201;veil de cr&#233;ature artificielle&quot;&gt;&#233;veil de cr&#233;ature artificielle&lt;/a&gt;&lt;/i&gt; (6 EP), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fouet-Dego-V.html&quot; title=&quot;Fouet d&amp;#39;ego V&quot;&gt;fouet d&#39;ego V&lt;/a&gt;&lt;/i&gt; (7 EP, DD 25), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Image-Psychique.html&quot; title=&quot;Image psychique&quot;&gt;image psychique&lt;/a&gt;&lt;/i&gt; (9 EP), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pulsation-Synaptique-Supr&#234;me.html&quot; title=&quot;Pulsation synaptique supr&#234;me&quot;&gt;pulsation synaptique supr&#234;me&lt;/a&gt;&lt;/i&gt; (5 EP, DD 23), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Surcharge-Synaptique.html&quot; title=&quot;Surcharge synaptique&quot;&gt;surcharge synaptique&lt;/a&gt;&lt;/i&gt; (5 EP, DD 23